t("Dark Hair 1", "深色头发1", "_t")
t("Dark Beard 2", "深色络腮胡2", "_t")
t("Skin Color 1", "皮肤颜色1", "_t")
t("Skin Color 2", "皮肤颜色2", "_t")
t("Skin Color 3", "皮肤颜色3", "_t")
t("Skin Color 4", "皮肤颜色4", "_t")
